                for (int k = 0; k < 4; ++k) {
                    dp[u][k] = (dp[u][k] + tmp[k]) % MOD;
                }
            }
            // 统计以 u 为最浅节点的幸运集
            ans = (ans + dp[u][3]) % MOD;
        }
    }

    cout << ans << "\n";
    return 0;
}
